import React, { useEffect, useRef, useState } from 'react';
import L from 'leaflet';
import { jsPDF } from 'jspdf';
import { ROUTE_POLICIES, choosePolicy } from './modules/ai/policies.js';
import { incidentAdvisory, matchHospitals, rankTeams } from './modules/ai/triage.js';
import { search as aiSearch } from './modules/ai/search.js';
